import { createMemo, onCleanup, onMount, Setter, type JSX, type ParentComponent } from "solid-js";

import SpatialWrapper from "#core/ui/external/js-spatial-navigation/spatial-wrapper.js";
import { SnUnfocusedEvent } from "#core/ui/external/js-spatial-navigation/spatial_navigation.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import {
	DefaultNavigationRules,
	FocusContext,
	FocusContextProvider,
	FocusNavigationRulesMap,
	FocusSortOrder,
	isContextFocusable,
	isFocusableAFocusContext,
} from "#core/ui-next/services/focus.js";
import { createPropsRefSignal } from "#core/ui-next/utilities/solid-utilities.js";

// Directive imports get destroyed by tree-shaking and auto-formatting - prevent that
export const PROTECTED_IMPORTS = [isContextFocusable];

export interface BaseSlotProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/**
	 * Name is used for debugging purposes. If unset, slot will just be called "VSlot" or "HSlot"
	 */
	name?: string;
	/**
	 * Is focus disabled for this slot?
	 * Affects visual style of components within the slot.
	 */
	disabled?: boolean;
	/**
	 * Is focus disabled for this slot?
	 * Does not Affect the visual style of components within the slot.
	 */
	disableFocus?: boolean;
	/**
	 * Determines the sort order of focusables in the slot
	 * Note: Sort order is not reactive after initilization
	 */
	sortOrder?: FocusSortOrder;
	/**
	 * Should navigation be reversed?
	 */
	isNavigationReversed?: boolean;
	/**
	 * When true, navigation is locked to this slot and cannot escape.
	 * All navigation attempts will be marked as handled.
	 */
	lockNavigation?: boolean;
	/**
	 * Setter that gets called with the focus context for the slot
	 */
	setFocusContext?: Setter<FocusContextProvider | undefined>;
	/**
	 * Auto focus this element?
	 * Note: This must initially be set to true or false to react to changes
	 * If set to undefined initally, this will NOT register updates.
	 */
	autoFocus?: boolean;
}

export interface SlotProps extends BaseSlotProps {
	/**
	 * The name of the slot; set as the data-name property - useful for debugging or searching the DOM tree. Default: Activatable
	 */
	name?: string;
	/**
	 * A map of focus navigation rules used to define the behavior of the slot.
	 */
	navRules: FocusNavigationRulesMap;
}

const SlotComponent: ParentComponent<SlotProps> = (props) => {
	const [root, setRoot] = createPropsRefSignal<HTMLElement>(() => props.ref);

	const navigationHandler = (context: FocusContextProvider, action: InputNavigationAction) => {
		// If this component is disabled, return false
		if (props.disabled || props.disableFocus) {
			return false;
		}

		// If a child context is focused, let it try to handle the navigation
		const curFocus = context.currentFocus();
		if (isFocusableAFocusContext(curFocus)) {
			if (curFocus.navigate(action)) {
				return true;
			}
		}

		// Otherwise, try to handle the navigation using the provided rules
		if (props.navRules.get(action)?.(context)) {
			return true;
		}

		// If navigation is locked, always mark as handled to prevent escaping this slot
		if (props.lockNavigation) {
			return true;
		}

		// If the navigation failed, let the parent context know
		return false;
	};

	const focusContext = new FocusContextProvider(root, navigationHandler, props.name ?? "Slot", props.sortOrder);
	const isFocusable = createMemo(() => !props.disabled && !props.disableFocus && focusContext.hasChildren());
	onMount(() => props.setFocusContext?.(focusContext));

	return (
		<div
			{...props}
			ref={setRoot}
			use:isContextFocusable={[focusContext, isFocusable(), props.autoFocus]}
			classList={{
				...props.classList,
				disabled: props.disabled,
			}}
			data-name={props.name ?? "Slot"}
			tabIndex={props.tabIndex ?? -1}
			on:focus={() => focusContext.focusCurrentOrDefault()}
		>
			<FocusContext.Provider value={focusContext}>{props.children}</FocusContext.Provider>
		</div>
	);
};

/**
 * The base slot component. Should not be used directly, except by other slot implmentations.
 * Default implementation: {@link SlotComponent}
 * @param {BaseSlotProps} props See {@link BaseSlotProps} for a full list of properties
 */
export const Slot = ComponentRegistry.register("Slot", SlotComponent);

const VSlotComponent: ParentComponent<BaseSlotProps> = (props) => {
	return (
		<Slot
			{...props}
			navRules={
				props.isNavigationReversed ? DefaultNavigationRules.verticalReversed : DefaultNavigationRules.vertical
			}
			class={`flex flex-col ${props.class ?? ""}`}
			name={props.name ? `${props.name}(VSlot)` : "VSlot"}
		/>
	);
};

/**
 * The vertically oriented slot component.
 * Allows for controller navigation horizontally.
 * ```tsx
 * <VSlot>
 * ...
 * </VSlot>
 * ```
 * Default implementation: {@link VSlotComponent}
 * @param {SlotProps} props See {@link SlotProps} for a full list of properties
 */
export const VSlot = ComponentRegistry.register("VSlot", VSlotComponent);

const HSlotComponent: ParentComponent<BaseSlotProps> = (props) => {
	return (
		<Slot
			{...props}
			navRules={
				props.isNavigationReversed
					? DefaultNavigationRules.horizontalReversed
					: DefaultNavigationRules.horizontal
			}
			class={`flex flex-row ${props.class ?? ""}`}
			name={props.name ? `${props.name}(HSlot)` : "HSlot"}
		/>
	);
};

/**
 * The horizontally oriented slot component.
 * Allows for controller navigation horizontally.
 * ```tsx
 * <HSlot>
 * ...
 * </HSlot>
 * ```
 * Default implementation: {@link HSlotComponent}
 * @param {SlotProps} props See {@link SlotProps} for a full list of properties
 */
export const HSlot = ComponentRegistry.register("HSlot", HSlotComponent);

export interface SpatialSlotProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/**
	 * Is focus disabled for this slot?
	 * Affects visual style of components within the slot.
	 */
	disabled?: boolean;
	/**
	 * Is focus disabled for this slot?
	 * Does not Affect the visual style of components within the slot.
	 */
	disableFocus?: boolean;
	/**
	 * The name of the slot; set as the data-name and section-id. Must be set for spatial slots.
	 */
	name: string;
	/**
	 * Auto focus this element?
	 */
	autoFocus?: boolean;
}

const SpatialSlotComponent: ParentComponent<SpatialSlotProps> = (props) => {
	let ref!: HTMLDivElement;
	let focusContext: FocusContextProvider | undefined = undefined;

	function spatialNavigate(direction: string, context: FocusContextProvider) {
		if (!focusContext) {
			focusContext = context;
		}

		const lastFocus = document.activeElement;
		SpatialWrapper.navigate(props.name, context.getFocuableChildren(), direction);
		const navSucceeded = lastFocus != document.activeElement;
		return navSucceeded;
	}

	const spatialNavigationRules = new Map([
		[InputNavigationAction.UP, (context: FocusContextProvider) => spatialNavigate("up", context)],
		[InputNavigationAction.DOWN, (context: FocusContextProvider) => spatialNavigate("down", context)],
		[InputNavigationAction.LEFT, (context: FocusContextProvider) => spatialNavigate("left", context)],
		[InputNavigationAction.RIGHT, (context: FocusContextProvider) => spatialNavigate("right", context)],
		[InputNavigationAction.NONE, (context: FocusContextProvider) => context.focusCurrent()],
	]) as FocusNavigationRulesMap;

	function onElementUnfocused(event: SnUnfocusedEvent) {
		// The spatial-navigation.js library is bluring the current target element to change the focus so let our FocusManager handle it.
		if (!event.detail.native && event.detail.nextElement) {
			const target = event.detail.nextElement;
			focusContext?.focusChild(target);

			event.preventDefault();
			event.stopImmediatePropagation();
		}
	}

	onMount(() => {
		ref.setAttribute("sectionId", props.name);
		ref.addEventListener("sn:willunfocus", onElementUnfocused);
	});

	onCleanup(() => {
		ref.removeEventListener("sn:willunfocus", onElementUnfocused);
	});

	return (
		<Slot
			{...props}
			ref={(e) => {
				ref = e;
			}}
			name={`${props.name}(SpatialSlot)`}
			navRules={spatialNavigationRules}
			autoFocus={props.autoFocus}
		/>
	);
};

export const SpatialSlot = ComponentRegistry.register("SpatialSlot", SpatialSlotComponent);
